with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الاستشعار عن بعد والأرصاد الفضائية المتقدمة','القنوات الطيفية والأقمار الجيوستيشـنرية والقطبية والاسترجاع الإشعاعي ومنتجات الغلاف الجوي والسطح.',53,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'القنوات الفضائية وتحليل السحب',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الاسترجاع الإشعاعي والمنتجات التطبيقية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('satellite-radiance-fundamentals','أساسيات الإشعاع الفضائي','الإشعاع الطيفي ومصادر الإشارة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تقيس أجهزة الأقمار الصناعية الإشعاع الصاعد ضمن نطاقات طيفية محددة، ثم تُفسر الإشارة وفق خصائص السطح والغلاف الجوي والهندسة الشمسية أو الهندسة الحرارية. تختلف دلالة القناة باختلاف طولها الموجي وعرضها الطيفي وحساسية الكاشف."},{"type":"heading","text":"أساس القياس والتفسير"},{"type":"text","text":"يعتمد أساسيات الإشعاع الفضائي على فهم الاستجابة الطيفية للجهاز وهندسة الرصد والخصائص الجوية والسطحية. يجب مراجعة وصف المنتج ومعايرته وأعلام الجودة والوحدات قبل تفسير القيم أو مقارنتها بمصادر أخرى."},{"type":"heading","text":"سير العمل"},{"type":"list","items":["تحقق من اسم المنتج والقناة والطول الموجي ووقت الالتقاط.","افحص أعلام الجودة والسحب وزاوية الرصد والبيكسلات غير الصالحة.","اختر منطقة الدراسة وحدد خصائص السطح والظروف الجوية.","استخرج المتغيرات المطلوبة مع الاحتفاظ بالبيانات الوصفية.","قارن النتائج بقياسات مستقلة وناقش حدود الدقة والتمثيل المكاني."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل منتج فضائي","text":"اختر مشهداً فضائياً واضحاً وطبق خطوات أساسيات الإشعاع الفضائي على منطقة معروفة الخصائص. قارن النتيجة بمنتج مستقل أو قياس أرضي متزامن، ثم وثق أسباب الاختلاف المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن بين قناة مرئية وقناة تحت حمراء وحدد ما الذي تقيسه كل منهما فعلياً."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["تجاهل أعلام الجودة أو القيم المفقودة.","الخلط بين الإشارة المقاسة والمتغير المسترجع.","مقارنة بكسل فضائي بمحطة دون مراعاة التمثيل المكاني.","إغفال توقيت المرور وزاوية الرصد.","استخدام منتج خارج شروط صلاحيته الموصى بها."]},{"type":"callout","text":"قاعدة أساسية: المنتج الفضائي ليس قياساً مباشراً لكل متغير جوي؛ افهم آلية القياس والاسترجاع قبل تفسير الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم أساسيات الإشعاع الفضائي أداة رصد واسعة النطاق، وتزداد قيمته عند دمجه مع معلومات الرصد الأرضي والتحقق المستقل."}]}'::jsonb,6760,50,'["شرح مبادئ أساسيات الإشعاع الفضائي","تقييم جودة المنتج الفضائي","مقارنة الاسترجاع ببيانات مستقلة"]'::jsonb,'القنوات الفضائية وتحليل السحب'),
('geostationary-satellite-imagery','صور الأقمار الجيوستيشـنرية','التغطية المستمرة والتطور الزمني','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"توفر الأقمار الجيوستيشـنرية رصداً متكرراً لنصف الكرة أو المنطقة التي تغطيها، ما يسمح بتتبع نمو السحب والحمل الحراري وحركة الأنظمة. تتغير الدقة المكانية والزمنية والطيفية حسب الجهاز والقناة."},{"type":"heading","text":"أساس القياس والتفسير"},{"type":"text","text":"يعتمد صور الأقمار الجيوستيشـنرية على فهم الاستجابة الطيفية للجهاز وهندسة الرصد والخصائص الجوية والسطحية. يجب مراجعة وصف المنتج ومعايرته وأعلام الجودة والوحدات قبل تفسير القيم أو مقارنتها بمصادر أخرى."},{"type":"heading","text":"سير العمل"},{"type":"list","items":["تحقق من اسم المنتج والقناة والطول الموجي ووقت الالتقاط.","افحص أعلام الجودة والسحب وزاوية الرصد والبيكسلات غير الصالحة.","اختر منطقة الدراسة وحدد خصائص السطح والظروف الجوية.","استخرج المتغيرات المطلوبة مع الاحتفاظ بالبيانات الوصفية.","قارن النتائج بقياسات مستقلة وناقش حدود الدقة والتمثيل المكاني."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل منتج فضائي","text":"اختر مشهداً فضائياً واضحاً وطبق خطوات صور الأقمار الجيوستيشـنرية على منطقة معروفة الخصائص. قارن النتيجة بمنتج مستقل أو قياس أرضي متزامن، ثم وثق أسباب الاختلاف المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"تابع خلية حملية عبر سلسلة صور زمنية وحدد مراحل تطورها."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["تجاهل أعلام الجودة أو القيم المفقودة.","الخلط بين الإشارة المقاسة والمتغير المسترجع.","مقارنة بكسل فضائي بمحطة دون مراعاة التمثيل المكاني.","إغفال توقيت المرور وزاوية الرصد.","استخدام منتج خارج شروط صلاحيته الموصى بها."]},{"type":"callout","text":"قاعدة أساسية: المنتج الفضائي ليس قياساً مباشراً لكل متغير جوي؛ افهم آلية القياس والاسترجاع قبل تفسير الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم صور الأقمار الجيوستيشـنرية أداة رصد واسعة النطاق، وتزداد قيمته عند دمجه مع معلومات الرصد الأرضي والتحقق المستقل."}]}'::jsonb,6770,50,'["شرح مبادئ صور الأقمار الجيوستيشـنرية","تقييم جودة المنتج الفضائي","مقارنة الاسترجاع ببيانات مستقلة"]'::jsonb,'القنوات الفضائية وتحليل السحب'),
('polar-orbiting-satellite-observations','رصد الأقمار ذات المدار القطبي','التغطية العالمية والدقة المكانية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتيح المدارات القطبية تغطية واسعة للعالم مع مرور القمر فوق مناطق مختلفة في أوقات محددة. تفيد في قياسات الغلاف الجوي والسطح، لكن التغطية الزمنية المحلية أقل استمرارية من الجيوستيشـنري."},{"type":"heading","text":"أساس القياس والتفسير"},{"type":"text","text":"يعتمد رصد الأقمار ذات المدار القطبي على فهم الاستجابة الطيفية للجهاز وهندسة الرصد والخصائص الجوية والسطحية. يجب مراجعة وصف المنتج ومعايرته وأعلام الجودة والوحدات قبل تفسير القيم أو مقارنتها بمصادر أخرى."},{"type":"heading","text":"سير العمل"},{"type":"list","items":["تحقق من اسم المنتج والقناة والطول الموجي ووقت الالتقاط.","افحص أعلام الجودة والسحب وزاوية الرصد والبيكسلات غير الصالحة.","اختر منطقة الدراسة وحدد خصائص السطح والظروف الجوية.","استخرج المتغيرات المطلوبة مع الاحتفاظ بالبيانات الوصفية.","قارن النتائج بقياسات مستقلة وناقش حدود الدقة والتمثيل المكاني."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل منتج فضائي","text":"اختر مشهداً فضائياً واضحاً وطبق خطوات رصد الأقمار ذات المدار القطبي على منطقة معروفة الخصائص. قارن النتيجة بمنتج مستقل أو قياس أرضي متزامن، ثم وثق أسباب الاختلاف المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن ما يمكن استخلاصه من مرور قطبي واحد مع سلسلة جيوستيشـنرية."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["تجاهل أعلام الجودة أو القيم المفقودة.","الخلط بين الإشارة المقاسة والمتغير المسترجع.","مقارنة بكسل فضائي بمحطة دون مراعاة التمثيل المكاني.","إغفال توقيت المرور وزاوية الرصد.","استخدام منتج خارج شروط صلاحيته الموصى بها."]},{"type":"callout","text":"قاعدة أساسية: المنتج الفضائي ليس قياساً مباشراً لكل متغير جوي؛ افهم آلية القياس والاسترجاع قبل تفسير الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم رصد الأقمار ذات المدار القطبي أداة رصد واسعة النطاق، وتزداد قيمته عند دمجه مع معلومات الرصد الأرضي والتحقق المستقل."}]}'::jsonb,6780,50,'["شرح مبادئ رصد الأقمار ذات المدار القطبي","تقييم جودة المنتج الفضائي","مقارنة الاسترجاع ببيانات مستقلة"]'::jsonb,'القنوات الفضائية وتحليل السحب'),
