('land-surface-temperature-retrieval','استرجاع حرارة سطح الأرض','الانبعاثية وتصحيح الغلاف الجوي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تُسترجع حرارة سطح الأرض من الإشعاع الحراري بعد تقدير الانبعاثية وتصحيح تأثيرات الغلاف الجوي. تختلف حرارة السطح عن حرارة الهواء، وتتأثر بنوع الغطاء الأرضي والرطوبة والوقت المحلي."},{"type":"heading","text":"أساس القياس والتفسير"},{"type":"text","text":"يعتمد استرجاع حرارة سطح الأرض على فهم الاستجابة الطيفية للجهاز وهندسة الرصد والخصائص الجوية والسطحية. يجب مراجعة وصف المنتج ومعايرته وأعلام الجودة والوحدات قبل تفسير القيم أو مقارنتها بمصادر أخرى."},{"type":"heading","text":"سير العمل"},{"type":"list","items":["تحقق من اسم المنتج والقناة والطول الموجي ووقت الالتقاط.","افحص أعلام الجودة والسحب وزاوية الرصد والبيكسلات غير الصالحة.","اختر منطقة الدراسة وحدد خصائص السطح والظروف الجوية.","استخرج المتغيرات المطلوبة مع الاحتفاظ بالبيانات الوصفية.","قارن النتائج بقياسات مستقلة وناقش حدود الدقة والتمثيل المكاني."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل منتج فضائي","text":"اختر مشهداً فضائياً واضحاً وطبق خطوات استرجاع حرارة سطح الأرض على منطقة معروفة الخصائص. قارن النتيجة بمنتج مستقل أو قياس أرضي متزامن، ثم وثق أسباب الاختلاف المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن حرارة سطح جاف وغطاء نباتي في وقت الظهيرة، وفسر الاختلاف."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["تجاهل أعلام الجودة أو القيم المفقودة.","الخلط بين الإشارة المقاسة والمتغير المسترجع.","مقارنة بكسل فضائي بمحطة دون مراعاة التمثيل المكاني.","إغفال توقيت المرور وزاوية الرصد.","استخدام منتج خارج شروط صلاحيته الموصى بها."]},{"type":"callout","text":"قاعدة أساسية: المنتج الفضائي ليس قياساً مباشراً لكل متغير جوي؛ افهم آلية القياس والاسترجاع قبل تفسير الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم استرجاع حرارة سطح الأرض أداة رصد واسعة النطاق، وتزداد قيمته عند دمجه مع معلومات الرصد الأرضي والتحقق المستقل."}]}'::jsonb,6910,50,'["شرح مبادئ استرجاع حرارة سطح الأرض","تقييم جودة المنتج الفضائي","مقارنة الاسترجاع ببيانات مستقلة"]'::jsonb,'الاسترجاع الإشعاعي والمنتجات التطبيقية'),
('sea-surface-temperature-satellite','حرارة سطح البحر من الأقمار الصناعية','النافذة الحرارية والتصحيح الرطوبي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تُقدر حرارة سطح البحر من قنوات تحت حمراء أو ميكروية وفق ظروف الرصد. تتطلب القنوات الحرارية الصافية سماءً خالية نسبياً من السحب، بينما تتأثر المنتجات الميكروية بعوامل أخرى مثل المطر والرياح."},{"type":"heading","text":"أساس القياس والتفسير"},{"type":"text","text":"يعتمد حرارة سطح البحر من الأقمار الصناعية على فهم الاستجابة الطيفية للجهاز وهندسة الرصد والخصائص الجوية والسطحية. يجب مراجعة وصف المنتج ومعايرته وأعلام الجودة والوحدات قبل تفسير القيم أو مقارنتها بمصادر أخرى."},{"type":"heading","text":"سير العمل"},{"type":"list","items":["تحقق من اسم المنتج والقناة والطول الموجي ووقت الالتقاط.","افحص أعلام الجودة والسحب وزاوية الرصد والبيكسلات غير الصالحة.","اختر منطقة الدراسة وحدد خصائص السطح والظروف الجوية.","استخرج المتغيرات المطلوبة مع الاحتفاظ بالبيانات الوصفية.","قارن النتائج بقياسات مستقلة وناقش حدود الدقة والتمثيل المكاني."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل منتج فضائي","text":"اختر مشهداً فضائياً واضحاً وطبق خطوات حرارة سطح البحر من الأقمار الصناعية على منطقة معروفة الخصائص. قارن النتيجة بمنتج مستقل أو قياس أرضي متزامن، ثم وثق أسباب الاختلاف المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد متى تفضل منتج حرارة سطح البحر الحراري ومتى تحتاج مصدراً بديلاً."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["تجاهل أعلام الجودة أو القيم المفقودة.","الخلط بين الإشارة المقاسة والمتغير المسترجع.","مقارنة بكسل فضائي بمحطة دون مراعاة التمثيل المكاني.","إغفال توقيت المرور وزاوية الرصد.","استخدام منتج خارج شروط صلاحيته الموصى بها."]},{"type":"callout","text":"قاعدة أساسية: المنتج الفضائي ليس قياساً مباشراً لكل متغير جوي؛ افهم آلية القياس والاسترجاع قبل تفسير الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم حرارة سطح البحر من الأقمار الصناعية أداة رصد واسعة النطاق، وتزداد قيمته عند دمجه مع معلومات الرصد الأرضي والتحقق المستقل."}]}'::jsonb,6920,50,'["شرح مبادئ حرارة سطح البحر من الأقمار الصناعية","تقييم جودة المنتج الفضائي","مقارنة الاسترجاع ببيانات مستقلة"]'::jsonb,'الاسترجاع الإشعاعي والمنتجات التطبيقية'),
('satellite-precipitation-estimation','تقدير الهطول من الأقمار الصناعية','القمم الباردة والميكروويف والمعايرة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تستخدم تقديرات الهطول الفضائية مؤشرات سحابية حرارية وقياسات ميكروية لاستنتاج المطر، وتعاير عادة بمقاييس أرضية ورادارات. تختلف الدقة حسب نوع الهطول والتضاريس والسطح والفترة الزمنية."},{"type":"heading","text":"أساس القياس والتفسير"},{"type":"text","text":"يعتمد تقدير الهطول من الأقمار الصناعية على فهم الاستجابة الطيفية للجهاز وهندسة الرصد والخصائص الجوية والسطحية. يجب مراجعة وصف المنتج ومعايرته وأعلام الجودة والوحدات قبل تفسير القيم أو مقارنتها بمصادر أخرى."},{"type":"heading","text":"سير العمل"},{"type":"list","items":["تحقق من اسم المنتج والقناة والطول الموجي ووقت الالتقاط.","افحص أعلام الجودة والسحب وزاوية الرصد والبيكسلات غير الصالحة.","اختر منطقة الدراسة وحدد خصائص السطح والظروف الجوية.","استخرج المتغيرات المطلوبة مع الاحتفاظ بالبيانات الوصفية.","قارن النتائج بقياسات مستقلة وناقش حدود الدقة والتمثيل المكاني."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل منتج فضائي","text":"اختر مشهداً فضائياً واضحاً وطبق خطوات تقدير الهطول من الأقمار الصناعية على منطقة معروفة الخصائص. قارن النتيجة بمنتج مستقل أو قياس أرضي متزامن، ثم وثق أسباب الاختلاف المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح لماذا قد تبالغ طريقة القمم الباردة في تقدير المطر في بعض الحالات."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["تجاهل أعلام الجودة أو القيم المفقودة.","الخلط بين الإشارة المقاسة والمتغير المسترجع.","مقارنة بكسل فضائي بمحطة دون مراعاة التمثيل المكاني.","إغفال توقيت المرور وزاوية الرصد.","استخدام منتج خارج شروط صلاحيته الموصى بها."]},{"type":"callout","text":"قاعدة أساسية: المنتج الفضائي ليس قياساً مباشراً لكل متغير جوي؛ افهم آلية القياس والاسترجاع قبل تفسير الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم تقدير الهطول من الأقمار الصناعية أداة رصد واسعة النطاق، وتزداد قيمته عند دمجه مع معلومات الرصد الأرضي والتحقق المستقل."}]}'::jsonb,6930,50,'["شرح مبادئ تقدير الهطول من الأقمار الصناعية","تقييم جودة المنتج الفضائي","مقارنة الاسترجاع ببيانات مستقلة"]'::jsonb,'الاسترجاع الإشعاعي والمنتجات التطبيقية'),
('satellite-data-quality-flags','أعلام جودة البيانات الفضائية','السحب والحواف والسطوح المختلطة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تصف أعلام الجودة ظروف القياس ومدى صلاحية البكسل للاسترجاع، مثل وجود سحب أو تلوث أو زاوية رصد غير ملائمة. يجب الاحتفاظ بالأعلام أثناء المعالجة وعدم التعامل مع كل القيم على أنها متساوية الثقة."},{"type":"heading","text":"أساس القياس والتفسير"},{"type":"text","text":"يعتمد أعلام جودة البيانات الفضائية على فهم الاستجابة الطيفية للجهاز وهندسة الرصد والخصائص الجوية والسطحية. يجب مراجعة وصف المنتج ومعايرته وأعلام الجودة والوحدات قبل تفسير القيم أو مقارنتها بمصادر أخرى."},{"type":"heading","text":"سير العمل"},{"type":"list","items":["تحقق من اسم المنتج والقناة والطول الموجي ووقت الالتقاط.","افحص أعلام الجودة والسحب وزاوية الرصد والبيكسلات غير الصالحة.","اختر منطقة الدراسة وحدد خصائص السطح والظروف الجوية.","استخرج المتغيرات المطلوبة مع الاحتفاظ بالبيانات الوصفية.","قارن النتائج بقياسات مستقلة وناقش حدود الدقة والتمثيل المكاني."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل منتج فضائي","text":"اختر مشهداً فضائياً واضحاً وطبق خطوات أعلام جودة البيانات الفضائية على منطقة معروفة الخصائص. قارن النتيجة بمنتج مستقل أو قياس أرضي متزامن، ثم وثق أسباب الاختلاف المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"أنشئ قواعد لتصفية منتج حرارة سطح الأرض باستخدام أعلام الجودة."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["تجاهل أعلام الجودة أو القيم المفقودة.","الخلط بين الإشارة المقاسة والمتغير المسترجع.","مقارنة بكسل فضائي بمحطة دون مراعاة التمثيل المكاني.","إغفال توقيت المرور وزاوية الرصد.","استخدام منتج خارج شروط صلاحيته الموصى بها."]},{"type":"callout","text":"قاعدة أساسية: المنتج الفضائي ليس قياساً مباشراً لكل متغير جوي؛ افهم آلية القياس والاسترجاع قبل تفسير الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم أعلام جودة البيانات الفضائية أداة رصد واسعة النطاق، وتزداد قيمته عند دمجه مع معلومات الرصد الأرضي والتحقق المستقل."}]}'::jsonb,6940,50,'["شرح مبادئ أعلام جودة البيانات الفضائية","تقييم جودة المنتج الفضائي","مقارنة الاسترجاع ببيانات مستقلة"]'::jsonb,'الاسترجاع الإشعاعي والمنتجات التطبيقية'),
('satellite-ground-data-fusion','دمج بيانات الأقمار والرصد الأرضي','المعايرة والتحقق والتكامل المكاني','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يجمع الدمج بين التغطية الفضائية الواسعة والقياسات الأرضية المباشرة، مع مراعاة اختلاف الحيز المكاني والارتفاع والتوقيت وتعريف المتغير. يفيد الدمج في التحقق والمعايرة وتحسين التغطية، لكنه يتطلب معالجة التمثيل المكاني."},{"type":"heading","text":"أساس القياس والتفسير"},{"type":"text","text":"يعتمد دمج بيانات الأقمار والرصد الأرضي على فهم الاستجابة الطيفية للجهاز وهندسة الرصد والخصائص الجوية والسطحية. يجب مراجعة وصف المنتج ومعايرته وأعلام الجودة والوحدات قبل تفسير القيم أو مقارنتها بمصادر أخرى."},{"type":"heading","text":"سير العمل"},{"type":"list","items":["تحقق من اسم المنتج والقناة والطول الموجي ووقت الالتقاط.","افحص أعلام الجودة والسحب وزاوية الرصد والبيكسلات غير الصالحة.","اختر منطقة الدراسة وحدد خصائص السطح والظروف الجوية.","استخرج المتغيرات المطلوبة مع الاحتفاظ بالبيانات الوصفية.","قارن النتائج بقياسات مستقلة وناقش حدود الدقة والتمثيل المكاني."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل منتج فضائي","text":"اختر مشهداً فضائياً واضحاً وطبق خطوات دمج بيانات الأقمار والرصد الأرضي على منطقة معروفة الخصائص. قارن النتيجة بمنتج مستقل أو قياس أرضي متزامن، ثم وثق أسباب الاختلاف المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم مقارنة بين تقدير فضائي ومجموعة محطات مع مراعاة اختلاف مساحة تمثيل كل مصدر."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["تجاهل أعلام الجودة أو القيم المفقودة.","الخلط بين الإشارة المقاسة والمتغير المسترجع.","مقارنة بكسل فضائي بمحطة دون مراعاة التمثيل المكاني.","إغفال توقيت المرور وزاوية الرصد.","استخدام منتج خارج شروط صلاحيته الموصى بها."]},{"type":"callout","text":"قاعدة أساسية: المنتج الفضائي ليس قياساً مباشراً لكل متغير جوي؛ افهم آلية القياس والاسترجاع قبل تفسير الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم دمج بيانات الأقمار والرصد الأرضي أداة رصد واسعة النطاق، وتزداد قيمته عند دمجه مع معلومات الرصد الأرضي والتحقق المستقل."}]}'::jsonb,6950,50,'["شرح مبادئ دمج بيانات الأقمار والرصد الأرضي","تقييم جودة المنتج الفضائي","مقارنة الاسترجاع ببيانات مستقلة"]'::jsonb,'الاسترجاع الإشعاعي والمنتجات التطبيقية')
)
insert into public.academy_lessons(course_id,chapter_id,unit_id,chapter_title,unit_title,slug,title,summary,content,published,sort_order,estimated_minutes,learning_objectives,level)
select c.id,ch.id,case when d.unit_title='القنوات الفضائية وتحليل السحب' then u1.id else u2.id end,'الاستشعار عن بعد والأرصاد الفضائية المتقدمة',d.unit_title,d.slug,d.title,d.summary,d.content,false,d.ord,d.mins,d.objectives,'advanced'
from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,level=excluded.level;